add_action( 'woocommerce_login_form_start', 'perfectpixel_login_intro_text' );
add_action( 'woocommerce_register_form_start', 'perfectpixel_register_intro_text', 5 );

function perfectpixel_login_intro_text() {
	if ( is_account_page() && '' !== trim( '{{login_intro_text}}' ) ) {
		echo '<div class="perfectpixel-login-intro">' . wp_kses_post( '{{login_intro_text}}' ) . '</div>';
	}
}

function perfectpixel_register_intro_text() {
	if ( is_account_page() && '' !== trim( '{{register_intro_text}}' ) ) {
		echo '<div class="perfectpixel-register-intro">' . wp_kses_post( '{{register_intro_text}}' ) . '</div>';
	}
}
